flags.typeql:
match
$t isa tweet, has favorites $f;
contains (containing_tweet: $t, contained_link: $l);
sort $f desc;
limit 3;
fetch {
  "url": $l.link_url
};

match
$u isa user, has screen_name "neo4j";
posts (author: $u, content: $t);
retweets (original_tweet: $t, retweeting_tweet: $rt);
reduce $count = count($rt) groupby $t;
match $count > 100;
sort $count desc;
limit 3;
fetch { "text": $t.text, "retweet_count": $count };

match
$u isa user, has screen_name "neo4j";
posts (author: $u, content: $t);
$ret isa retweets (original_tweet: $t);
reduce $count = count($ret) groupby $t;
match $count > 50;
fetch { "tweet_text": $t.text, "retweet_count": $count };

match
$me isa me, has screen_name "neo4j", has statuses $me_statuses;
$user isa user, has statuses $user_statuses;
follows (follower: $me, followed: $user);
$user_statuses > $me_statuses;
fetch {
  "screen_name": $user.screen_name,
  "statuses": $user_statuses
};

match
$me isa me;
posts (author: $me, content: $tweet);
mentions (source_tweet: $tweet, mentioned_user: $user);
$user isa user;
$tweet has created_at $ca;
sort $ca asc;
limit 3;
fetch {
  "created_at": $tweet.created_at,
  "tweet_id": $tweet.tweet_id,
  "text": $tweet.text,
  "favorites": $tweet.favorites
};

match
$t isa tweet;
$ret isa retweets (original_tweet: $t);
reduce $count = count($ret) groupby $t;
sort $count desc;
limit 3;
fetch { "tweet_text": $t.text, "tweet_id": $t.tweet_id, "retweet_count": $count };

match
$t isa tweet;
retweets (original_tweet: $t, retweeting_tweet: $rt);
reduce $count = count($rt) groupby $t;
sort $count desc;
limit 3;
fetch { "text": $t.text, "retweet_count": $count };

match
$t isa tweet;
retweets (original_tweet: $t, retweeting_tweet: $rt);
reduce $count = count($rt) groupby $t;
match
$count > 100;
$t has created_at $ca;
sort $ca asc;
limit 3;
fetch {
  "tweet": $t.text,
  "created_at": $ca,
  "retweet_count": $count
};

match
$u isa user, has screen_name "neo4j";
posts (author: $u, content: $t);
contains (containing_tweet: $t, contained_link: $l);
$t has created_at $ca;
$ca >= 2021-01-01T00:00:00;
$ca < 2021-02-01T00:00:00;
sort $ca;
limit 3;
fetch {
  "tweet_text": $t.text,
  "link_url": $l.link_url,
  "created_at": $ca
};

match
$m isa me, has screen_name "neo4j";
$u isa user, has following $f;
amplifies (amplifier: $u, amplified_user: $m);
$f > 1000;
limit 3;
fetch {
  "name": $u.name,
  "screen_name": $u.screen_name,
  "following": $f
};

with fun max_betweenness() -> double:
  match $u isa user, has betweenness $b;
  return max($b);
match
  $u isa user, has betweenness $b;
  let $max_b = max_betweenness();
  $b == $max_b;
  mentions (source_tweet: $t, mentioned_user: $u);
  $t has created_at $ca;
sort $ca asc;
limit 3;
fetch { "tweet_id": $t.tweet_id, "text": $t.text, "created_at": $t.created_at };

match
$u isa user, has screen_name "neo4j";
posts (author: $u, content: $t);
retweets (original_tweet: $t, retweeting_tweet: $rt);
reduce $count = count($rt) groupby $u, $t;
sort $count desc;
limit 3;
fetch { "tweet": $t.text, "retweets": $count };

match
$t isa tweet, has id_str $id_str, has text $text, has created_at $ca;
$u isa user, has name "Neo4j";
mentions (source_tweet: $t, mentioned_user: $u);
$ca > 2021-01-01T00:00:00;
sort $ca;
fetch {
  "tweet_id": $id_str,
  "tweet_text": $text,
  "created_at": $ca
};

match
$t isa tweet;
retweets (original_tweet: $t, retweeting_tweet: $rt);
reduce $count = count($rt) groupby $t;
sort $count desc;
limit 5;
fetch { "tweet_text": $t.text, "tweet_id": $t.tweet_id, "retweet_count": $count };

match
  $m isa me, has screen_name "neo4j";
  $u isa user, has following $f;
  amplifies (amplifier: $m, amplified_user: $u);
  $f > 5000;
sort $f desc;
limit 5;
fetch {
  "screen_name": $u.screen_name,
  "following": $f
};

match
$me isa me;
$rel isa similar_to (source_user: $me, similar_user: $user);
$rel has score $s;
sort $s desc;
limit 5;
fetch {
  "screen_name": $user.screen_name,
  "score": $s
};
